import 'package:flutter/material.dart';

// Параметрлері бар StatefulWidget
class Counter extends StatefulWidget {
  // === ПАРАМЕТРЛЕР (өзгермейтін) ===
  final int initialValue;           // Бастапқы мән
  final int step;                    // Өзгеру қадамы
  final void Function(int)? onChanged;  // Өзгерген кездегі callback

  const Counter({
    super.key,
    this.initialValue = 0,
    this.step = 1,
    this.onChanged,
  });

  @override
  State<Counter> createState() => _CounterState();
}

class _CounterState extends State<Counter> {
  // === КҮЙ (өзгермелі) ===
  late int count;

  @override
  void initState() {
    super.initState();
    // widget параметрінен инициализациялаймыз
    count = widget.initialValue;
  }

  void increment() {
    setState(() {
      count += widget.step;  // step параметрін қолданамыз
    });
    // Callback бар болса шақырамыз
    widget.onChanged?.call(count);
  }

  void decrement() {
    setState(() {
      count -= widget.step;
    });
    widget.onChanged?.call(count);
  }

  @override
  Widget build(BuildContext context) {
    return Row(
      mainAxisSize: MainAxisSize.min,
      children: [
        IconButton(
          onPressed: decrement,
          icon: const Icon(Icons.remove),
        ),
        Text(
          '$count',
          style: const TextStyle(fontSize: 24),
        ),
        IconButton(
          onPressed: increment,
          icon: const Icon(Icons.add),
        ),
      ],
    );
  }
}

// === ҚОЛДАНУ ===

class ShoppingCart extends StatelessWidget {
  const ShoppingCart({super.key});

  @override
  Widget build(BuildContext context) {
    return Column(
      children: [
        const Text('Тауар саны:'),
        Counter(
          initialValue: 1,    // 1-ден бастаймыз
          step: 1,            // Қадам = 1
          onChanged: (value) {
            // Жаңа мәнді аламыз!
            print('Жаңа сан: $value');
          },
        ),
      ],
    );
  }
}

